{"path": "styles.css", "content": "/* =========================================================
   Fix2Live Credit Solutions
   Brutalist editorial showroom on warm gray canvas
   Single typeface: Manrope (Geist Mono for numeric / technical labels)
   ========================================================= */

:root {
  /* Surfaces */
  --canvas: #e5e5e5;
  --card: #ffffff;
  --mist: #f3f3f3;
  --ink: #000000;
  --ink-1: #181818;
  --ink-2: #1f1f1f;
  --ink-3: #272727;
  --ink-4: #313131;

  /* Neutrals */
  --ash: #c6c6c6;
  --smoke: #979797;
  --slate: #444444;
  --silver: #c0c0c0;

  /* Accent */
  --gold: #ffd700;

  /* Spacing tokens */
  --s25: 2px;
  --s50: 4px;
  --s75: 8px;
  --s100: 12px;
  --s200: 16px;
  --s300: 24px;
  --s400: 32px;
  --s500: 40px;
  --s600: 48px;
  --s700: 64px;
  --s800: 80px;
  --s900: 96px;

  /* Motion */
  --ease: cubic-bezier(0.32, 0.72, 0, 1);
}

*,
*::before,
*::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: "Manrope", system-ui, sans-serif;
  font-size: 1rem;
  line-height: 1.5rem;
  font-weight: 400;
  letter-spacing: -0.011em;
  text-wrap: pretty;
  overflow-x: hidden;
}

img, svg { display: block; max-width: 100%; }
a { color: inherit; }
ul, ol { margin: 0; padding: 0; }
p { margin: 0; }

::selection { background: var(--gold); color: var(--ink); }

/* ---------- Accessibility ---------- */
.skip-link {
  position: absolute;
  left: var(--s200);
  top: var(--s200);
  z-index: 200;
  transform: translateY(-200%);
  background: var(--ink);
  color: #fff;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 600;
  padding: var(--s75) var(--s100);
  border-radius: 8px;
  transition: transform 0.35s var(--ease);
}
.skip-link:focus { transform: translateY(0); }

:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}
.invert :focus-visible,
.stats :focus-visible,
.cta-block :focus-visible,
.site-foot :focus-visible {
  outline-color: var(--gold);
}

/* ---------- Layout ---------- */
.wrap, .container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding-inline: var(--s300);
}

section { padding-block: var(--s800); }
.section-head { max-width: 680px; margin-bottom: var(--s600); }
.section-head .mono-label { margin-bottom: var(--s200); }
.section-lede, .lede {
  font-size: 1.125rem;
  line-height: 1.75rem;
  color: var(--slate);
  max-width: 680px;
  margin-top: var(--s200);
}

.divider { height: 1px; background: var(--ink-4); }

/* ---------- Typography ---------- */
.display,
h1, h2 {
  font-weight: 700;
  text-transform: uppercase;
  line-height: 0.9;
  letter-spacing: -0.03em;
  text-wrap: balance;
  margin: 0;
}

.hero-title { font-size: 3rem; line-height: 1; max-width: 680px; }

.display-sm, h2 { font-size: 2.25rem; line-height: 2.5rem; }

h3, .card-title {
  font-size: 1.25rem;
  line-height: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  margin: 0;
  text-wrap: balance;
}

.mono-label,
.mono {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 0.75rem;
  line-height: 1rem;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: var(--slate);
  display: block;
}
.invert .mono-label, .stats .mono-label, .cta-block .mono-label, .site-foot .mono-label { color: var(--ash); }

.tag {
  display: inline-flex;
  align-items: center;
  gap: var(--s50);
  background: var(--gold);
  color: var(--ink);
  border-radius: 9999px;
  padding: var(--s25) var(--s100);
  font-size: 0.75rem;
  line-height: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  white-space: nowrap;
}
.tag-silver { background: var(--silver); }
.tag-ghost { background: transparent; color: var(--ash); border: 1px solid var(--ink-4); }

.gold { color: var(--gold); }
.hi-gold {
  background: var(--gold);
  color: var(--ink);
  padding: 0 var(--s50);
  font-weight: 600;
  text-decoration: none;
}
.hi-gold:hover { text-decoration: underline; }

/* Hero gradient heading (light theme: #000 to #666) */
.grad-text {
  background: linear-gradient(90deg, #000000 0%, #666666 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  display: inline-block;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--s75);
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  padding: var(--s75) var(--s100);
  border-radius: 8px;
  border: 0;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 0.7s var(--ease), color 0.7s var(--ease),
    transform 0.7s var(--ease), border-color 0.7s var(--ease), opacity 0.7s var(--ease);
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: scale(0.98); }

.btn-dark { background: var(--ink); color: #fff; }
.btn-dark:hover { background: var(--ink-3); }

.btn-ghost {
  background: transparent;
  color: var(--slate);
  border: 1.5px solid var(--slate);
  border-radius: 4px;
}
.btn-ghost:hover { background: var(--card); color: var(--ink); border-color: var(--ink); }

.btn-gold { background: var(--gold); color: var(--ink); }
.btn-gold:hover { background: #ffe75c; }

.btn-light { background: #fff; color: var(--ink); }
.btn-light:hover { background: var(--mist); }

.btn-sm { font-size: 0.875rem; line-height: 1.25rem; }
.btn[disabled], .btn.is-loading { cursor: progress; opacity: 0.85; transform: none; }

.btn-link {
  display: inline-flex;
  align-items: center;
  gap: var(--s50);
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.7s var(--ease), color 0.7s var(--ease);
}
.btn-link:hover { border-color: currentColor; }

/* Skeleton loader inside submit button */
.skeleton { display: none; height: 16px; width: 132px; background: rgba(0, 0, 0, 0.25); }
.btn.is-loading .skeleton { display: block; animation: pulse 1.1s var(--ease) infinite; }
.btn.is-loading .btn-label { display: none; }
@keyframes pulse { 0%, 100% { opacity: 0.35; } 50% { opacity: 0.9; } }

/* ---------- Navigation ---------- */
.nav-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 60;
  display: flex;
  justify-content: center;
  padding-top: var(--s300);
  pointer-events: none;
}
.nav-pill {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: var(--s300);
  width: max-content;
  max-width: calc(100% - 32px);
  background: var(--card);
  border-radius: 9999px;
  padding: var(--s75) var(--s75) var(--s75) var(--s300);
  transition: background-color 0.7s var(--ease);
}
.nav-pill .btn { border-radius: 9999px; }

.brand {
  display: flex;
  align-items: center;
  gap: var(--s75);
  text-decoration: none;
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  white-space: nowrap;
}
.brand-mark {
  width: 24px;
  height: 24px;
  background: var(--ink);
  color: var(--gold);
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 0.75rem;
  line-height: 1rem;
  font-weight: 400;
  display: grid;
  place-items: center;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--s300);
  list-style: none;
}
.nav-links a {
  position: relative;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 500;
  color: var(--slate);
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: -0.01em;
  transition: color 0.7s var(--ease);
}
.nav-links a:hover { color: var(--ink); }
.nav-links a.is-current { color: var(--ink); }
.nav-links a.is-current::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -8px;
  width: 4px;
  height: 4px;
  margin-left: -2px;
  background: var(--gold);
}

.nav-burger {
  position: relative;
  display: none;
  width: 40px;
  height: 40px;
  background: var(--mist);
  border: 0;
  border-radius: 9999px;
  cursor: pointer;
}
.nav-burger span {
  position: absolute;
  left: 11px;
  width: 18px;
  height: 2px;
  background: var(--ink);
  transition: transform 0.7s var(--ease), top 0.7s var(--ease);
}
.nav-burger span:nth-child(1) { top: 16px; }
.nav-burger span:nth-child(2) { top: 22px; }
.nav-burger.is-open span:nth-child(1) { top: 19px; transform: rotate(45deg); }
.nav-burger.is-open span:nth-child(2) { top: 19px; transform: rotate(-45deg); }

/* Fluid island modal */
.nav-modal {
  position: fixed;
  inset: 0;
  z-index: 55;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: rgba(255, 255, 255, 0.8);
  -webkit-backdrop-filter: blur(40px);
  backdrop-filter: blur(40px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.7s var(--ease), visibility 0.7s var(--ease);
}
.nav-modal.is-open { opacity: 1; visibility: visible; }
.nav-modal-inner { padding: var(--s300); }
.nav-modal-links { list-style: none; display: grid; gap: var(--s200); }
.nm-link {
  display: inline-block;
  font-size: 2.25rem;
  line-height: 2.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: -0.03em;
  text-decoration: none;
  transform: translateY(48px);
  opacity: 0;
  transition: transform 0.8s var(--ease), opacity 0.8s var(--ease);
}
.nav-modal.is-open .nm-link { transform: translateY(0); opacity: 1; }
.nav-modal.is-open li:nth-child(1) .nm-link { transition-delay: 0.1s; }
.nav-modal.is-open li:nth-child(2) .nm-link { transition-delay: 0.15s; }
.nav-modal.is-open li:nth-child(3) .nm-link { transition-delay: 0.2s; }
.nav-modal.is-open li:nth-child(4) .nm-link { transition-delay: 0.25s; }
.nav-modal.is-open li:nth-child(5) .nm-link { transition-delay: 0.3s; }
.nav-modal-foot {
  margin-top: var(--s600);
  display: flex;
  flex-wrap: wrap;
  gap: var(--s200);
  align-items: center;
}

/* ---------- Hero ---------- */
.hero { padding-top: var(--s900); margin-top: var(--s700); padding-bottom: var(--s800); }
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--s600);
  align-items: center;
}
.hero-copy > * + * { margin-top: var(--s300); }
.hero-sub { max-width: 680px; font-size: 1.125rem; line-height: 1.75rem; color: var(--slate); }
.hero-actions { display: flex; flex-wrap: wrap; gap: var(--s200); align-items: center; }
.risk-note { font-size: 0.875rem; line-height: 1.25rem; color: var(--slate); }
.proof-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--s200);
  padding-top: var(--s300);
}
.proof-line .mono-label { display: inline-block; }

/* Hero visual */
.hero-visual { display: grid; gap: var(--s200); }
.score-card { background: var(--card); border-radius: 24px; padding: var(--s300); }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: var(--s200); }
.score-num {
  font-size: 4.5rem;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-top: var(--s200);
}
.score-sub { font-size: 0.875rem; line-height: 1.25rem; color: var(--smoke); }
.meter { display: flex; gap: var(--s50); margin: var(--s200) 0; }
.seg { flex: 1; height: 24px; background: var(--ash); }
.seg.on { background: var(--ink); }
.seg.gold { background: var(--gold); }
.score-meta { display: flex; flex-wrap: wrap; gap: var(--s200); align-items: center; justify-content: space-between; }

.disputes-card { background: var(--ink); color: #fff; border-radius: 24px; padding: var(--s300); }
.dl { list-style: none; display: grid; gap: var(--s75); margin-top: var(--s200); }
.dl li {
  display: flex;
  align-items: flex-start;
  gap: var(--s75);
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--ash);
}
.dl li strong { color: #fff; font-weight: 600; }
.dl i, .dl .ph { color: var(--gold); font-size: 1rem; line-height: 1.25rem; }

/* ---------- Stats band ---------- */
.stats-block {
  background: var(--ink);
  color: #fff;
  border-radius: 24px;
  padding: var(--s600) var(--s300);
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--s500) var(--s300);
}
.stat-num {
  font-size: 2.25rem;
  line-height: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}
.stat-label { font-size: 0.875rem; line-height: 1.25rem; color: var(--ash); margin-top: var(--s75); }

/* ---------- Tagline reveal ---------- */
.tagline { padding-block: var(--s900); }
.tagline-text {
  font-size: 2.25rem;
  line-height: 2.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: -0.03em;
  max-width: 680px;
  text-wrap: balance;
}
.tagline-text .w {
  display: inline-block;
  color: rgba(0, 0, 0, 0.3);
  transition: color 0.7s var(--ease);
}
.tagline-text .w.is-on { color: var(--ink); }
.tagline-text .w.accent.is-on { color: var(--ink); background: var(--gold); }

/* ---------- Cards / grids ---------- */
.card { background: var(--card); border-radius: 24px; padding: var(--s300); }
.card.invert { background: var(--ink); color: #fff; }
.card.invert p, .card.invert li { color: var(--ash); }

.grid-2, .grid-3, .grid-4 { display: grid; gap: var(--s300); grid-template-columns: minmax(0, 1fr); }

.icon-box {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  background: var(--mist);
  color: var(--ink);
  font-size: 1.5rem;
  margin-bottom: var(--s300);
}
.invert .icon-box { background: var(--ink-3); color: var(--gold); }
.benefit p, .svc-card p, .step p { margin-top: var(--s100); color: var(--slate); }
.card.invert p { color: var(--ash); }

/* Steps */
.step { background: var(--card); border-radius: 24px 24px 0 0; padding: var(--s300); }
.step-num {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 0.75rem;
  line-height: 1rem;
  letter-spacing: -0.03em;
  color: var(--smoke);
  margin-bottom: var(--s600);
  display: block;
}
.step-meta { margin-top: var(--s300); }

/* Services */
.svc-list { list-style: none; display: grid; gap: var(--s75); margin-top: var(--s200); }
.svc-list li {
  display: flex;
  gap: var(--s75);
  align-items: flex-start;
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--slate);
}
.card.invert .svc-list li { color: var(--ash); }
.svc-list i, .svc-list .ph { color: var(--ink); font-size: 1rem; }
.card.invert .svc-list i, .card.invert .svc-list .ph { color: var(--gold); }

/* Reviews */
.review { background: var(--card); border-radius: 24px; padding: var(--s300); display: flex; flex-direction: column; gap: var(--s200); }
.stars { display: flex; gap: var(--s25); color: var(--ink); font-size: 1rem; }
.review blockquote { margin: 0; font-size: 1rem; line-height: 1.5rem; }
.reviewer { display: flex; align-items: center; gap: var(--s100); margin-top: auto; }
.avatar {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 0.75rem;
  line-height: 1rem;
  background: var(--ink);
  color: #fff;
}
.avatar.gold-av { background: var(--gold); color: var(--ink); }
.avatar.silver-av { background: var(--silver); color: var(--ink); }
.avatar.mist-av { background: var(--mist); color: var(--ink); }
.who { font-size: 0.875rem; line-height: 1.25rem; font-weight: 600; }
.who span { display: block; font-weight: 400; color: var(--smoke); }

/* ---------- FAQ ---------- */
.faq-list { display: grid; gap: var(--s75); }
.faq-item {
  background: var(--card);
  border-radius: 24px;
  padding: var(--s300);
}
.faq-item summary {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--s300);
  cursor: pointer;
  font-size: 1.125rem;
  line-height: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.011em;
  list-style: none;
}
.faq-item summary::-webkit-details-marker { display: none; }
.faq-ico { flex: 0 0 auto; font-size: 1.25rem; transition: transform 0.7s var(--ease); }
.faq-item[open] .faq-ico { transform: rotate(45deg); }
.faq-a { max-width: 680px; margin-top: var(--s100); color: var(--slate); }
.faq-a p + p { margin-top: var(--s100); }

/* ---------- Final CTA + form ---------- */
.cta-block {
  background: var(--ink);
  color: #fff;
  border-radius: 24px;
  padding: var(--s600);
}
.cta-grid { display: grid; gap: var(--s600); grid-template-columns: minmax(0, 1fr); align-items: start; }
.cta-copy h2 { color: #fff; }
.cta-copy p { color: var(--ash); margin-top: var(--s300); max-width: 680px; }
.cta-contacts { display: grid; gap: var(--s100); margin-top: var(--s400); }
.cta-contacts a { display: inline-flex; align-items: center; gap: var(--s75); text-decoration: none; font-weight: 600; }
.cta-contacts a:hover { text-decoration: underline; }

.lead-form { background: var(--ink-2); border-radius: 24px; padding: var(--s300); display: grid; gap: var(--s200); }
.field label { display: block; margin-bottom: var(--s50); font-family: "Geist Mono", ui-monospace, monospace; font-size: 0.75rem; line-height: 1rem; letter-spacing: -0.03em; text-transform: uppercase; color: var(--ash); }
.field input, .field select, .field textarea {
  width: 100%;
  background: var(--ink-1);
  color: #fff;
  border: 1px solid var(--ink-4);
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.5rem;
  padding: var(--s100);
  border-radius: 8px;
  transition: border-color 0.7s var(--ease), background-color 0.7s var(--ease);
}
.field textarea { min-height: 96px; resize: vertical; }
.field input::placeholder, .field textarea::placeholder { color: var(--smoke); }
.field input:hover, .field select:hover, .field textarea:hover { border-color: var(--smoke); }
.field input:focus, .field select:focus, .field textarea:focus { outline: none; border-color: var(--gold); background: var(--ink-3); }
.err { display: none; margin-top: var(--s50); font-size: 0.75rem; line-height: 1rem; color: var(--gold); }
.field.is-invalid .err { display: block; }
.field.is-invalid input, .field.is-invalid select, .field.is-invalid textarea { border-color: var(--gold); }
.form-note { font-size: 0.75rem; line-height: 1rem; color: var(--smoke); }
.form-success {
  display: none;
  background: var(--ink-3);
  border-radius: 8px;
  padding: var(--s300);
}
.form-success.is-visible { display: block; }
.form-success h3 { color: #fff; }
.form-success p { color: var(--ash); margin-top: var(--s100); }
.form-success .mono-label { margin-top: var(--s200); }
.lead-form.is-hidden { display: none; }

/* ---------- Footer ---------- */
.site-foot {
  background: var(--ink);
  color: #fff;
  border-radius: 24px 24px 0 0;
  padding: var(--s800) 0 var(--s300);
  margin-top: var(--s800);
}
.foot-grid { display: grid; gap: var(--s500); grid-template-columns: minmax(0, 1fr); }
.foot-col h3 { font-size: 0.875rem; line-height: 1.25rem; color: var(--ash); margin-bottom: var(--s200); }
.foot-col ul { list-style: none; display: grid; gap: var(--s75); }
.foot-col a { text-decoration: none; font-size: 0.875rem; line-height: 1.25rem; color: #fff; transition: color 0.7s var(--ease); }
.foot-col a:hover { color: var(--gold); }
.foot-col p { font-size: 0.875rem; line-height: 1.25rem; color: var(--ash); }
.legal-item { margin-top: var(--s200); }
.legal-item summary { cursor: pointer; font-size: 0.875rem; line-height: 1.25rem; font-weight: 600; list-style: none; }
.legal-item summary::-webkit-details-marker { display: none; }
.legal-item p { margin-top: var(--s75); color: var(--smoke); max-width: 680px; }
.foot-bottom {
  margin-top: var(--s600);
  padding-top: var(--s300);
  display: flex;
  flex-wrap: wrap;
  gap: var(--s200);
  justify-content: space-between;
  align-items: center;
}
.foot-bottom p, .foot-bottom .mono-label { color: var(--smoke); }

/* ---------- Scroll reveal ---------- */
.reveal {
  opacity: 0;
  transform: translateY(64px);
  filter: blur(6px);
  transition: opacity 0.9s var(--ease), transform 0.9s var(--ease), filter 0.9s var(--ease);
  will-change: opacity, transform;
}
.reveal.is-in { opacity: 1; transform: translateY(0); filter: blur(0); }
.reveal.d1 { transition-delay: 0.1s; }
.reveal.d2 { transition-delay: 0.15s; }
.reveal.d3 { transition-delay: 0.2s; }
.reveal.d4 { transition-delay: 0.25s; }

/* ---------- Responsive ---------- */
@media (min-width: 640px) {
  .grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stats-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .hero-title { font-size: 4.5rem; }
  .display-sm, h2 { font-size: 3rem; line-height: 1; }
  .tagline-text { font-size: 3rem; line-height: 1; }
  .foot-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (min-width: 900px) {
  .nav-burger { display: none; }
  .grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .hero-grid { grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr); gap: var(--s700); }
  .cta-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--s700); }
  .foot-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .stats-block { padding: var(--s600); }
}

@media (min-width: 1100px) {
  .hero-title { font-size: 6rem; }
  .tagline-text { font-size: 3.75rem; }
  .stat-num { font-size: 3rem; line-height: 1; }
}

@media (max-width: 899px) {
  .nav-links, .nav-pill > .btn { display: none; }
  .nav-burger { display: block; }
  .nav-pill { padding-right: var(--s75); }
  .cta-block { padding: var(--s300); }
  section { padding-block: var(--s700); }
  .tagline { padding-block: var(--s800); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
  .reveal { opacity: 1; transform: none; filter: none; }
  .tagline-text .w { color: var(--ink); }
}
